import { Controller, Post, Body, Injectable, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Transport, MicroserviceOptions, MessagePattern, Payload } from '@nestjs/microservices';

// Internal pricing engine microservice
// Handles discount calculation for enterprise customers

interface DiscountRequest {
  customerId: string;
  tier: string;
  amount: number;
  metadata?: Record<string, any>;
}

@Injectable()
class PricingService {
  private readonly tierMultipliers: Record<string, number> = {
    bronze: 0.95,
    silver: 0.90,
    gold: 0.85,
    platinum: 0.75,
  };

  calculateDiscount(request: DiscountRequest): any {
    // Type confusion: 'amount' is expected to be number but no runtime validation
    // If amount is a string like "100" it gets coerced, but if it's an object
    // with valueOf/toString, arbitrary code paths can be triggered
    const multiplier = this.tierMultipliers[request.tier] || 1.0;

    // Vulnerable: no type checking on amount - object with custom valueOf()
    // can cause prototype pollution or unexpected behavior
    const finalPrice = request.amount * multiplier;

    // Secondary issue: metadata is spread without sanitization
    const response = {
      customerId: request.customerId,
      originalAmount: request.amount,
      discountedAmount: finalPrice,
      tier: request.tier,
      ...request.metadata,
    };

    // If metadata contains __proto__ or constructor keys, prototype pollution occurs
    return response;
  }

  // Internal admin endpoint - relies on network isolation for auth
  overridePricing(customerId: string, config: any): any {
    // Type confusion: config.rules is expected to be array but if object is passed
    // the for...in loop iterates over prototype chain
    const rules = config.rules;
    const applied: string[] = [];

    if (rules && typeof rules === 'object') {
      // Vulnerable to prototype pollution via crafted rules object
      for (const key in rules) {
        // No hasOwnProperty check - iterates inherited properties
        (Object.prototype as any)[key] = rules[key];
        applied.push(key);
      }
    }

    return { customerId, appliedRules: applied, status: 'updated' };
  }
}

@Controller()
class PricingController {
  constructor(private readonly pricingService: PricingService) {}

  @MessagePattern({ cmd: 'calculate_discount' })
  handleDiscount(@Payload() data: DiscountRequest) {
    return this.pricingService.calculateDiscount(data);
  }

  @MessagePattern({ cmd: 'override_pricing' })
  handleOverride(@Payload() data: { customerId: string; config: any }) {
    return this.pricingService.overridePricing(data.customerId, data.config);
  }

  @Post('/internal/discount')
  httpDiscount(@Body() body: DiscountRequest) {
    return this.pricingService.calculateDiscount(body);
  }

  @Post('/internal/admin/override')
  httpOverride(@Body() body: { customerId: string; config: any }) {
    return this.pricingService.overridePricing(body.customerId, body.config);
  }
}

@Module({
  controllers: [PricingController],
  providers: [PricingService],
})
class PricingModule {}

async function bootstrap() {
  const app = await NestFactory.create(PricingModule);

  // TCP microservice transport - no auth layer
  app.connectMicroservice<MicroserviceOptions>({
    transport: Transport.TCP,
    options: { host: '0.0.0.0', port: 3001 },
  });

  await app.startAllMicroservices();
  await app.listen(3000);
  console.log('Pricing microservice listening on :3000 (HTTP) and :3001 (TCP)');
}

bootstrap();
